{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0) to counteract overconfidence.",
    "Increase forecast sensitivity to recent price spikes — apply a lag correction: if true price rises > 5% from 3-day avg, reduce forecast by 10-15%.",
    "Apply mean reversion bias: if forecast deviates > 20% from 30-day moving average, revert toward the average by 5-10% per day.",
    "For high sentiment (sentiment > 0.5), reduce forecast by 5-10% to avoid overestimating bullish momentum.",
    "After sharp price spikes, apply a 2-day cooling-off rule: forecast = previous day’s forecast * 0.95 to avoid overshoot.",
    "When sentiment is positive but price is trending down, apply a downward bias correction: reduce forecast by 3-5% to avoid false optimism."
  ]
}
